import{_ as a,o as t,c as r,a2 as o}from"./chunks/framework.CWgsre3x.js";const p=JSON.parse('{"title":"Frequently asked questions","description":"","frontmatter":{},"headers":[],"relativePath":"help/faq.md","filePath":"help/faq.md"}'),i={name:"help/faq.md"};function n(s,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Reference release</p><p>Reference v0.7.26, not a live installation audit or commercial activation approval. Confirm installed version, permissions, configuration and acceptance.</p></div><h2 id="do-staff-need-an-application-installed" tabindex="-1">Do staff need an application installed? <a class="header-anchor" href="#do-staff-need-an-application-installed" aria-label="Permalink to &quot;Do staff need an application installed?&quot;">​</a></h2><p>No native installation is required for browser access. Use an approved HTTPS deployment and supported devices; mobile compatibility and GPS acceptance must be tested separately. <a href="/system-requirements/">System requirements</a></p><h2 id="how-do-we-create-an-administrator-dispatcher-or-driver-login" tabindex="-1">How do we create an administrator, dispatcher or driver login? <a class="header-anchor" href="#how-do-we-create-an-administrator-dispatcher-or-driver-login" aria-label="Permalink to &quot;How do we create an administrator, dispatcher or driver login?&quot;">​</a></h2><p>Request authorized backend provisioning with the minimum necessary role. A driver roster entry does not automatically create a login or link it to assignments. Staff use individual email/password credentials. Public applications do not create accounts. <a href="/plus/staff-administration.html">Staff administration</a></p><h2 id="can-a-passenger-book-without-email" tabindex="-1">Can a passenger book without email? <a class="header-anchor" href="#can-a-passenger-book-without-email" aria-label="Permalink to &quot;Can a passenger book without email?&quot;">​</a></h2><p>Yes. Use the actual passenger telephone and leave email empty if not supplied. Do not invent an address. This is different from staff authentication. <a href="/tutorials/phone-only-booking.html">Phone-only booking</a></p><h2 id="which-services-can-we-configure" tabindex="-1">Which services can we configure? <a class="header-anchor" href="#which-services-can-we-configure" aria-label="Permalink to &quot;Which services can we configure?&quot;">​</a></h2><p>The release supports one-way and return transfers, hourly chauffeur service and private tours. Configure applicable markets, locations, capacities and prices, then test each service sold. <a href="/getting-started/first-reservation.html">First reservation</a></p><h2 id="why-does-a-route-require-a-manual-quote" tabindex="-1">Why does a route require a manual quote? <a class="header-anchor" href="#why-does-a-route-require-a-manual-quote" aria-label="Permalink to &quot;Why does a route require a manual quote?&quot;">​</a></h2><p>A missing or invalid tariff is not a free ride. Review direction, time, class and applicable tariff rules. Use the authorized manual quotation process when a verified fare is unavailable. <a href="/plus/manual-quotations.html">Manual quotations</a></p><h2 id="can-different-drivers-perform-the-outward-and-return-legs" tabindex="-1">Can different drivers perform the outward and return legs? <a class="header-anchor" href="#can-different-drivers-perform-the-outward-and-return-legs" aria-label="Permalink to &quot;Can different drivers perform the outward and return legs?&quot;">​</a></h2><p>The release supports independent legs. Verify each leg&#39;s assignment, time, capacity, vehicle and progress separately. <a href="/plus/chauffeur-workspace.html">Chauffeur workspace</a></p><h2 id="why-was-a-dispatch-assignment-rejected" tabindex="-1">Why was a dispatch assignment rejected? <a class="header-anchor" href="#why-was-a-dispatch-assignment-rejected" aria-label="Permalink to &quot;Why was a dispatch assignment rejected?&quot;">​</a></h2><p>Check the reservation and quotation status, full journey interval, driver duty or absence, vehicle maintenance, capacity and competing assignments. Refresh after a conflict; do not force the assignment. <a href="/plus/dispatch-schedule.html">Dispatch schedule</a></p><h2 id="can-i-take-partial-cash-and-hand-it-over-later" tabindex="-1">Can I take partial cash and hand it over later? <a class="header-anchor" href="#can-i-take-partial-cash-and-hand-it-over-later" aria-label="Permalink to &quot;Can I take partial cash and hand it over later?&quot;">​</a></h2><p>Record only cash actually received using the authorized workflow. Review the remaining balance and collecting chauffeur. Confirm physical office custody separately after actual handover. <a href="/plus/cash-management.html">Cash management</a></p><h2 id="are-online-payments-already-enabled" tabindex="-1">Are online payments already enabled? <a class="header-anchor" href="#are-online-payments-already-enabled" aria-label="Permalink to &quot;Are online payments already enabled?&quot;">​</a></h2><p>No live provider activation is established for this release. Each provider needs approved merchant credentials, callback and endpoint validation, acceptance and authorization. Viva credential descriptions disagree; Skrill refund is unsupported in the inspected adapter. <a href="/integrations/payment-api-setup.html">Payment setup</a></p><h2 id="can-customers-book-directly-from-our-website" tabindex="-1">Can customers book directly from our website? <a class="header-anchor" href="#can-customers-book-directly-from-our-website" aria-label="Permalink to &quot;Can customers book directly from our website?&quot;">​</a></h2><p>A separate gateway and publication workflow exist in source. Public intake remains disabled pending explicit approval. A website preview or active channel record alone does not enable public bookings. <a href="/plus/customer-booking-gateway.html">Customer gateway</a></p><h2 id="does-god-s-eye-track-every-driver-and-flight-automatically" tabindex="-1">Does God&#39;s Eye track every driver and flight automatically? <a class="header-anchor" href="#does-god-s-eye-track-every-driver-and-flight-automatically" aria-label="Permalink to &quot;Does God&#39;s Eye track every driver and flight automatically?&quot;">​</a></h2><p>The release includes a local geographic canvas, authorized on-duty GPS sharing and persistent manual flight/ferry observations. Licensed maps, physical GPS acceptance, automatic external arrival monitoring and scheduling remain outstanding. <a href="/integrations/live-tracking.html">Fleet tracking</a> and <a href="/plus/arrival-intelligence.html">Arrival intelligence</a></p><h2 id="are-whatsapp-email-sms-and-ai-already-connected" tabindex="-1">Are WhatsApp, email, SMS and AI already connected? <a class="header-anchor" href="#are-whatsapp-email-sms-and-ai-already-connected" aria-label="Permalink to &quot;Are WhatsApp, email, SMS and AI already connected?&quot;">​</a></h2><p>Adapter and conversational foundations exist; external transmission and provider use require separate configuration and authorization. A preview is not delivery; an AI draft is not a booking. <a href="/integrations/ai-messaging-setup.html">AI and messaging</a></p><h2 id="can-we-outsource-a-transfer-to-another-company" tabindex="-1">Can we outsource a transfer to another company? <a class="header-anchor" href="#can-we-outsource-a-transfer-to-another-company" aria-label="Permalink to &quot;Can we outsource a transfer to another company?&quot;">​</a></h2><p>Persistent subcontractor assignment and settlement workflows are implemented. Verify the approved supplier relationship, correct leg, agreed amount and actual settlement. This is not automatic external supplier dispatch. <a href="/plus/subcontractors.html">Subcontractors</a></p><h2 id="does-the-system-submit-mydata-or-edxeix-documents-live" tabindex="-1">Does the system submit myDATA or EDXEIX documents live? <a class="header-anchor" href="#does-the-system-submit-mydata-or-edxeix-documents-live" aria-label="Permalink to &quot;Does the system submit myDATA or EDXEIX documents live?&quot;">​</a></h2><p>No. The documented release has persistent sandbox records and blocks live submission. Follow approved statutory procedures and obtain separate regulatory acceptance. <a href="/integrations/regulatory-sandbox.html">Regulatory sandbox</a></p><h2 id="what-should-i-do-after-a-booking-or-payment-timeout" tabindex="-1">What should I do after a booking or payment timeout? <a class="header-anchor" href="#what-should-i-do-after-a-booking-or-payment-timeout" aria-label="Permalink to &quot;What should I do after a booking or payment timeout?&quot;">​</a></h2><p>Do not submit again blindly. Search for the existing reference and verify authoritative reservation or payment records. Escalate unresolved results to the authorized support owner. <a href="/developers/idempotency.html">Retry-safe creation</a> and <a href="/tutorials/payment-review.html">Payment review</a></p><h2 id="how-do-we-update-or-recover-the-system" tabindex="-1">How do we update or recover the system? <a class="header-anchor" href="#how-do-we-update-or-recover-the-system" aria-label="Permalink to &quot;How do we update or recover the system?&quot;">​</a></h2><p>Use the approved release-specific procedure and verified backup/recovery plan. The protected staging updater is not blanket commercial upgrade authorization. <a href="/plus/software-update-manager.html">Software updates</a> and <a href="/getting-started/backup-recovery.html">Recovery</a></p><h2 id="does-100-onboarding-mean-we-can-go-live" tabindex="-1">Does 100% onboarding mean we can go live? <a class="header-anchor" href="#does-100-onboarding-mean-we-can-go-live" aria-label="Permalink to &quot;Does 100% onboarding mean we can go live?&quot;">​</a></h2><p>No. Configuration readiness is separate from application acceptance, actual access tests, provider approval and business sign-off. <a href="/getting-started/go-live-checklist.html">Go-live checklist</a></p><p>See <a href="/help/feature-availability.html">Feature availability</a> and <a href="/help/glossary.html">Glossary</a>.</p>',37)])])}const m=a(i,[["render",n]]);export{p as __pageData,m as default};
